function printConfigSummary(config: Config): void {
  console.log('\n--- Configuration Summary ---\n')

  console.log('Telegram:')
  const tg = config.channels.telegram
  if (tg) {
    console.log(`  Bot token: ${tg.botToken.slice(0, 8)}...${tg.botToken.slice(-4)}`)
